previewCss:
.darma-loader-darma-b14-cpu-cores { --accent: var(--loader-color, #22c55e); --accent-2: var(--loader-secondary-color, #facc15); width: var(--loader-size, 100px); height: var(--loader-size, 100px); display: grid; grid-template-columns: repeat(2, 1fr); gap: 8%; padding: 11%; border-radius: 9%; background: linear-gradient(#1e293b, #0b1220); box-shadow: inset 0 0 0 2px #334155; }
.darma-loader-darma-b14-cpu-cores span { position: relative; overflow: hidden; border-radius: 3px; background: rgba(255, 255, 255, .08); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .12); }
.darma-loader-darma-b14-cpu-cores span::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b14-cpu-cores-core-load calc(var(--loader-speed, 1s) * 1.8) ease-in-out infinite; }
.darma-loader-darma-b14-cpu-cores span:nth-child(1) { --peak: 92%; }
.darma-loader-darma-b14-cpu-cores span:nth-child(2) { --peak: 62%; }
.darma-loader-darma-b14-cpu-cores span:nth-child(2)::after { animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b14-cpu-cores span:nth-child(3) { --peak: 100%; }
.darma-loader-darma-b14-cpu-cores span:nth-child(3)::after { animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b14-cpu-cores span:nth-child(4) { --peak: 46%; }
.darma-loader-darma-b14-cpu-cores span:nth-child(4)::after { animation-delay: calc(var(--loader-speed, 1s) * .9); }
@keyframes darma-loader-darma-b14-cpu-cores-core-load { 0%, 100% { height: 16%; } 50% { height: var(--peak); } }

